import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-10-02","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-10-02","date":"2024-10-02T00:00:00.000Z","updated":"2024-10-03T00:00:00.000Z","tags":["Ceph","RGW","多站点","版本控制","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-02.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-02.md","lastUpdated":1780459816000}'),i={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-02.md"};function l(n,e,s,h,c,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统中的多站点和版本问题讨论" tabindex="-1">会议主题：Ceph分布式存储系统中的多站点和版本问题讨论 <a class="header-anchor" href="#会议主题-ceph分布式存储系统中的多站点和版本问题讨论" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统中的多站点和版本问题讨论&quot;">​</a></h4><h4 id="参会人员-jane及其他相关研发人员" tabindex="-1">参会人员：Jane及其他相关研发人员 <a class="header-anchor" href="#参会人员-jane及其他相关研发人员" aria-label="Permalink to &quot;参会人员：Jane及其他相关研发人员&quot;">​</a></h4><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>多站点和版本问题</strong></p><ul><li><strong>问题描述</strong>：Jane报告了一个关于多站点配置中版本桶的问题。在删除多个对象版本后，生命周期管理（LC）在次要站点触发清理，但发现残留的OLH条目（Object Log History）未被清除，导致新上传的对象无法被正确识别为当前版本，从而可能导致数据丢失。</li><li><strong>讨论焦点</strong>：讨论了OLH条目的正确处理流程，包括何时以及如何清理这些条目。重点在于客户端逻辑中的协调机制，以及RGW（RADOS Gateway）在处理这些条目时的角色。</li><li><strong>解决方案探索</strong>：提出通过重置OLH条目的epoch来解决潜在问题，但考虑到了竞态条件。建议创建一个Tracker问题，并提供简单的复现步骤，以便进一步分析。</li></ul></li><li><p><strong>多站点同步机制</strong></p><ul><li><strong>同步问题</strong>：讨论了多站点设置中，主站点和次要站点在同时进行对象操作时的同步机制，特别是对象的放置和删除操作，以及如何通过BI Log（Bucket Index Log）解决冲突。</li><li><strong>关键点</strong>：强调了时间戳在同步机制中的重要性，以及如何通过BI Log确保各站点的一致性。</li></ul></li><li><p><strong>其他议题</strong></p><ul><li><strong>V1行为的多站点通知问题</strong>：讨论了是否需要在多站点模型中为特定行为（如通知）添加特殊处理。</li><li><strong>RGW测试套件问题</strong>：报告了RGW的所有测试套件因SELinux组查找失败而失败的问题，寻求基础设施团队的帮助。</li><li><strong>新版本发布</strong>：宣布了新版本的发布，并对参与测试和设计的Bloomberg团队表示感谢。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>创建一个Tracker问题，详细描述多站点和版本问题的复现步骤，以便进一步分析和解决。</li><li>继续讨论和探索多站点同步机制的优化方案。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>由Jane负责创建Tracker问题，并提供复现步骤。</li><li>研发团队继续关注和解决RGW测试套件的问题。</li><li>对新版本进行持续监控，确保稳定性和功能完整性。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统中的多站点和版本问题，包括OLH条目的处理、多站点同步机制以及新版本的发布。通过详细的讨论和解决方案探索，确定了后续的行动计划，以确保系统的稳定性和功能的完善。</p>',11)])])}const _=a(i,[["render",l]]);export{p as __pageData,_ as default};
